INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre) VALUES ('8ff47448-e291-56bd-8456-7adee558683c', 'f8611348-77a2-5c54-a802-2ae860e7694f', 1, 'Convocatoria · CFE-0001-CAAAA-0014-2026', '<p>COMISION FEDERAL DE ELECTRICIDAD</p>
<p>Con fundamento en el Artículo 134 de la Constitución Política de los Estados Unidos Mexicanos, Artículos 80 y 82 la Ley de la Empresa Pública del Estado, Comisión Federal de Electricidad, en las disposiciones 2 fracción I, 30, fracción I, inciso c), 31, 33, fracciones IV, VII y VIII, 34, 37, fracción I, 55 y 56, fracciones II, III y IV de las Disposiciones Generales en materia de adquisiciones, arrendamientos, contratación de servicios y ejecución de obras de la Comisión Federal de Electricidad:</p>
<table><thead><tr><th colspan="2">CFE-0001-CAAAA-0014-2026</th></tr><tr><th colspan="2">Sistema de cables de potencia Unidades 1 y 3 para la Central Hidroeléctrica Manuel Moreno Torres (Chicoasén)</th></tr></thead><tbody><tr><th scope="row">Fecha de publicación en Micrositio:</th><td>22/10/2026</td></tr><tr><th scope="row">Sesión de Aclaraciones:</th><td>28/10/2026, 10:00 hrs</td></tr><tr><th scope="row">Límite para presentación de ofertas:</th><td>5/11/2026, 11:00 hrs</td></tr><tr><th scope="row">Apertura Técnica:</th><td>5/11/2026, 11:30 hrs</td></tr><tr><th scope="row">Apertura Económica:</th><td>12/11/2026, 11:30 hrs</td></tr><tr><th scope="row">Fallo</th><td>19/11/2026, 13:00 hrs</td></tr></tbody></table>
<p>El Area Contratante que publica la presente convocatoria es la Gerencia de Abastecimientos de la CFE, a través de la Subgerencia de Adquisiciones y del Departamento de Concursos, cuyos contactos son: el Mtro. José Arturo Mejía Sánchez y el Lic. Daniel Miranda Velázquez, con domicilio en Río Ródano No. 14, piso 4, sala 402, Alcaldía Cuauhtémoc, C.P. 06500, Ciudad de México, teléfono (55) 5229 4400 ext. 83494, con los correos electrónicos: arturo.mejias@cfe.mx y daniel.miranda@cfe.mx. Las personas interesadas podrán obtener la Convocatoria y Pliego de Requisitos, a través del Micrositio de Concursos de la CFE en el sitio https://msc.cfe.mx/Aplicaciones/NCFE/Concursos/, a partir de la fecha de publicación en Micrositio.</p>
<p>CIUDAD DE MEXICO, A 27 DE OCTUBRE DE 2026.</p>
<p>SUBGERENTE DE ADQUISICIONES</p>
<p>L.A. JOSE AURELIO DE LA VEGA ANGELES</p>
<p>FIRMA ELECTRONICA.</p>
<p>(R.- 581603)</p>', 'convocatoria', 'CFE-0001-CAAAA-0014-2026', 'Cables de potencia de las unidades 1 y 3 de Chicoasén');
