INSERT INTO public.articulos (id, ley_id, orden, identificador, contenido, tipo_articulo, titulo_nombre, capitulo_nombre) VALUES ('a6496a3e-344b-5263-8d73-e653b0dac686', 'c47bd4ba-6926-5e55-8c59-4a9c97c7788d', 1, 'Convocatoria · CFE-0004-CACOT-0006-2026', '<p>COMISION FEDERAL DE ELECTRICIDAD</p>
<p>DIRECCION DE ADMINISTRACION</p>
<p>SUBDIRECCION DE CONTRATACION Y SERVICIOS</p>
<p>COORDINACION DE CONTRATACIONES DE OBRA Y SERVICIOS RELACIONADOS</p>
<p>GERENCIA DE CONTRATACIONES DE OBRA</p>
<p>CONVOCATORIA AL CONCURSO ABIERTO DE CARACTER INTERNACIONAL BAJO LA COBERTURA DE LOS TRATADOS</p>
<p>NUMERO CFE-0004-CACOT-0006-2026</p>
<p>Con fundamento en el Artículo 134 de la Constitución Política de los Estados Unidos Mexicanos, y en apego a la Disposición 73 de las “Disposiciones Generales en Materia de Adquisiciones, Arrendamientos, Contratación de Servicios y Ejecución de Obras de la Comisión Federal de Electricidad”, la Gerencia de Contrataciones de Obra, convoca a los interesados a participar en el Concurso Abierto de Carácter Internacional bajo la cobertura de los tratados Número CFE-0004-CACOT-0006-2026, para la contratación de los trabajos de la 366 SE Incremento de la cap de transf 230/115/69 kV en Zona Tijuana.</p>
<p>Los interesados podrán consultar el Pliego de Requisitos y Registrar su interés en participar a través del Sistema Electrónico de Contrataciones (Micrositio de Concursos) en la dirección electrónica: http://msc.cfe.mx/aplicaciones/NCFE/concursos.</p>
<p>El procedimiento de contratación se llevará a cabo con la siguiente programación:</p>
<table><tbody><tr><th scope="row">Visita al Sitio de los trabajos:</th><td colspan="2">Se efectuarán a las 09:30 horas, el día 20 de noviembre de 2026, siendo el punto de reunión Subestación Eléctrica Metrópoli Potencia, ubicada en km 20 de la carretera libre Tijuana - Tecate entronque con el Blv. Insurgentes (frente a Hyundai), del municipio de Tijuana, Estado de Baja California.</td></tr><tr><th scope="row">Sesión de aclaraciones:</th><td>24 de noviembre de 2026 10:00 horas</td><td rowspan="4">Los citados actos se llevarán a cabo a través del Sistema Electrónico de Contrataciones (Micrositio de Concursos)</td></tr><tr><th scope="row">Presentación de Ofertas y Apertura de Ofertas Técnicas:</th><td>06 de enero de 2027 10:00 horas</td></tr><tr><th scope="row">Apertura de Ofertas Económicas:</th><td>14 de enero de 2027 13:00 horas</td></tr><tr><th scope="row">Acto de Fallo:</th><td>22 de enero de 2027 13:00 horas</td></tr></tbody></table>
<p>El Area Contratante que publica la presente convocatoria es la Gerencia de Contrataciones de Obra de la CFE, con domicilio en Río Mississippi, número 71, 1er Piso, Colonia Cuauhtémoc, Alcaldía Cuauhtémoc, Código Postal 06500, Ciudad de México. El personal de contacto es el C.P. Antonio González Barrascout, Gerente y el Mtro. Héctor Omar Leal Nava, Jefe de Departamento, con correo electrónico omar.leal@cfe.mx.</p>
<p>ATENTAMENTE</p>
<p>CIUDAD DE MEXICO, A 27 DE OCTUBRE DE 2026.</p>
<p>AGENTE CONTRATANTE No. O1A0401</p>
<p>MTRO. HECTOR OMAR LEAL NAVA</p>
<p>RUBRICA.</p>
<p>(R.- 581635)</p>', 'convocatoria', 'CFE-0004-CACOT-0006-2026', 'Incremento de capacidad de transformación en la zona Tijuana');
